import{_ as t,o,c as n,ag as r}from"./chunks/framework.DzGOF12C.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"Java란","slug":"java란","link":"#java란","children":[]},{"level":2,"title":"프로그래밍 언어의 계층","slug":"프로그래밍-언어의-계층","link":"#프로그래밍-언어의-계층","children":[]},{"level":2,"title":"객체지향 개념 (자동차 비유)","slug":"객체지향-개념-자동차-비유","link":"#객체지향-개념-자동차-비유","children":[]},{"level":2,"title":"Java 프로그램 실행 과정 (5단계)","slug":"java-프로그램-실행-과정-5단계","link":"#java-프로그램-실행-과정-5단계","children":[]}],"relativePath":"computer/Java/01. Java 소개.md","filePath":"computer/Java/01. Java 소개.md"}'),e={name:"computer/Java/01. Java 소개.md"};function l(i,a,s,g,c,d){return o(),n("div",null,[...a[0]||(a[0]=[r('<h2 id="java란" tabindex="-1">Java란 <a class="header-anchor" href="#java란" aria-label="Permalink to &quot;Java란&quot;">​</a></h2><p>Java는 세계에서 가장 널리 쓰이는 프로그래밍 언어 중 하나로, **객체지향 프로그래밍(OOP)**을 핵심 방법론으로 채택한다. 기업용 소프트웨어, 인터넷 기반 애플리케이션, 안드로이드 앱 등에 광범위하게 쓰인다.</p><p><strong>Java 에디션</strong></p><ul><li><strong>Java SE (Standard Edition)</strong>: 범용 크로스플랫폼 애플리케이션 개발용</li><li><strong>Java EE (Enterprise Edition)</strong>: 대규모 분산 네트워킹/웹 애플리케이션용</li><li><strong>Java ME (Micro Edition)</strong>: 메모리 제약이 큰 소형 기기용</li></ul><h2 id="프로그래밍-언어의-계층" tabindex="-1">프로그래밍 언어의 계층 <a class="header-anchor" href="#프로그래밍-언어의-계층" aria-label="Permalink to &quot;프로그래밍 언어의 계층&quot;">​</a></h2><ul><li><strong>기계어(Machine Language)</strong>: 컴퓨터가 직접 이해하는 유일한 언어. 0과 1의 문자열, 기계 종속적</li><li><strong>어셈블리어(Assembly Language)</strong>: 기계어 연산을 영어 약어로 표현. <strong>어셈블러</strong>가 기계어로 변환</li><li><strong>고급 언어(High-Level Language)</strong>: 하나의 문장이 상당한 작업을 수행. <strong>컴파일러</strong>가 기계어로 변환하거나, <strong>인터프리터</strong>가 직접 실행</li></ul><h2 id="객체지향-개념-자동차-비유" tabindex="-1">객체지향 개념 (자동차 비유) <a class="header-anchor" href="#객체지향-개념-자동차-비유" aria-label="Permalink to &quot;객체지향 개념 (자동차 비유)&quot;">​</a></h2><ul><li><strong>클래스(Class)</strong>: 객체가 수행할 메서드들의 집합을 담는 프로그램 단위 (자동차의 설계도)</li><li><strong>객체(Object) / 인스턴스(Instance)</strong>: 클래스로부터 만들어진 실체 (설계도로 만든 실제 자동차)</li><li><strong>메서드(Method)</strong>: 작업을 수행하는 코드를 담고 있으며, 그 세부 구현을 사용자로부터 숨김 (가속 페달 — 내부 메커니즘을 몰라도 밟기만 하면 됨)</li><li><strong>속성(Attribute) / 인스턴스 변수</strong>: 객체가 가지는 상태 (자동차의 색상, 연료량 등). 각 객체는 자신만의 속성값을 가짐</li><li><strong>캡슐화(Encapsulation)</strong>: 속성과 메서드를 객체 안에 감싸고, 구현 세부사항을 객체 내부에 숨김 (<strong>정보 은닉</strong>)</li><li><strong>재사용(Reuse)</strong>: 하나의 클래스를 여러 번 재사용해 여러 객체를 만들 수 있음 — 검증된 클래스를 재사용하면 개발 시간 단축 + 신뢰성 향상</li><li><strong>메시지 전달</strong>: 객체에게 메시지를 보내는 것은 곧 그 객체의 메서드를 호출하는 것으로 구현됨 (가속 페달을 밟는 것 = &quot;더 빨리 가라&quot;는 메시지)</li><li><strong>상속(Inheritance)</strong>: 기존 클래스의 특성을 물려받아 새 클래스를 빠르게 만드는 방법 (컨버터블은 자동차의 한 종류지만, 지붕을 열고 닫는 고유 기능이 추가됨)</li></ul><p><strong>객체지향 분석/설계(OOAD)</strong>: 코드를 작성하기 전에 요구사항 분석(무엇을 해야 하는가)과 설계(어떻게 할 것인가)를 먼저 수행. **UML(Unified Modeling Language)**은 객체지향 시스템을 모델링하는 데 가장 널리 쓰이는 그래픽 표기법.</p><h2 id="java-프로그램-실행-과정-5단계" tabindex="-1">Java 프로그램 실행 과정 (5단계) <a class="header-anchor" href="#java-프로그램-실행-과정-5단계" aria-label="Permalink to &quot;Java 프로그램 실행 과정 (5단계)&quot;">​</a></h2><ol><li><strong>편집(Edit)</strong>: 에디터로 소스코드 작성, <code>.java</code> 확장자로 저장</li><li><strong>컴파일(Compile)</strong>: <code>javac Welcome.java</code> — 컴파일러가 소스코드를 <strong>바이트코드</strong>로 변환해 <code>.class</code> 파일 생성 (플랫폼 독립적)</li><li><strong>로드(Load)</strong>: JVM(Java Virtual Machine)이 클래스 로더를 통해 <code>.class</code> 파일을 메모리로 적재</li><li><strong>검증(Verify)</strong>: 바이트코드 검증기가 바이트코드의 유효성과 보안 규칙 위반 여부를 검사</li><li><strong>실행(Execute)</strong>: JVM이 바이트코드를 실행 — 인터프리터 방식과 <strong>JIT(Just-In-Time) 컴파일</strong>을 함께 사용해 성능 향상</li></ol><p><strong>JVM(Java Virtual Machine)</strong>: 가상 머신(VM) — 컴퓨터를 소프트웨어로 시뮬레이션. 동일한 JVM이 여러 플랫폼에 구현되어 있으면, 그 위에서 실행되는 프로그램은 플랫폼 독립적으로 동작함 (&quot;Write Once, Run Anywhere&quot;의 근거).</p><p><strong>Java 클래스 라이브러리(Java API)</strong>: 재사용 가능한 클래스·메서드의 모음. 패키지(package) 단위로 그룹화되어 있음.</p>',13)])])}const h=t(e,[["render",l]]);export{v as __pageData,h as default};
